/**
 * @file Shadow testing: adds or removes a user without their sign-in, scanned with the
 * operator's token. The discovery queries of this branch look the user up by id, so the token
 * needn't be theirs; the inbox opening mentions the operator, not them.
 *
 * Usage, from `apps/backend`, after building `@grn/core`:
 *
 *   pnpm shadow-user add <login>
 *   pnpm shadow-user remove <login>
 *
 * Environment (read from `.env` if present):
 * - `POSTGRES_URL`, `TOKEN_ENCRYPTION_KEY`: the shadow deployment's.
 * - `SHADOW_TOKEN`: the operator's GitHub token, a classic personal access token with no
 *   scopes (or a fine-grained one with public read access only), like the app's own sign-in
 *   token. It is stored, encrypted, as each shadow user's token.
 * - `OAUTH_REDIRECT_URI` (optional): its origin is the site the inbox opening links.
 */

import {
  AccessTokenCipher,
  createGraphQLFetcher,
  graphqlDocument,
  pool,
} from "@grn/core";

import { deleteAccount, signIn } from "./src/users/accounts.ts";
import type { GitHubIdentity } from "./src/users/accounts.ts";

const DEFAULT_SITE = "https://github-reactions-notifier.vercel.app";

const UserDocument = graphqlDocument<
  { user: GitHubIdentity | null },
  { login: string }
>(`
query shadowUser($login: String!) {
  user(login: $login) {
    id
    login
    createdAt
  }
}`);

const fetchUser = createGraphQLFetcher(UserDocument, "bearer");

const env = (name: string): string => {
  const value = process.env[name];
  if (!value) {
    throw new Error(`${name} is not set`);
  }
  return value;
};

/**
 * @param login The account to look up.
 * @param token The operator's token.
 * @returns The account, by its current login.
 */
const lookUp = async (
  login: string,
  token: string,
): Promise<GitHubIdentity> => {
  const response = await fetchUser({ login }, token);
  // Classic tokens list their scopes; fine-grained tokens send no such header.
  const scopes: unknown = response.headers["x-oauth-scopes"];
  if (typeof scopes === "string" && scopes.trim() !== "") {
    throw new Error(
      `SHADOW_TOKEN has scopes (${scopes}): it could read private content. Use one without scopes.`,
    );
  }
  const { data, errors } = response.data;
  if (errors?.length) {
    throw new Error(
      `user query failed: ${errors.map((e) => e.message).join("; ")}`,
    );
  }
  if (!data.user) {
    throw new Error(`No GitHub user ${login}`);
  }
  return data.user;
};

const main = async (): Promise<void> => {
  const [command, login] = process.argv.slice(2);
  if ((command !== "add" && command !== "remove") || !login) {
    console.error("Usage: shadow-user add|remove <login>");
    process.exitCode = 2;
    return;
  }
  if (!pool) {
    throw new Error("POSTGRES_URL is not set");
  }
  const token = env("SHADOW_TOKEN");
  const identity = await lookUp(login, token);

  if (command === "remove") {
    const existed = await deleteAccount(pool, identity.id);
    console.log(
      existed
        ? `Removed ${identity.login} (${identity.id}). Its inbox issue stays open.`
        : `${identity.login} (${identity.id}) was not a user.`,
    );
    return;
  }

  const redirectUri = process.env["OAUTH_REDIRECT_URI"];
  const result = await signIn(pool, identity, token, {
    cipher: AccessTokenCipher.fromEnv(),
    siteUrl: redirectUri ? new URL(redirectUri).origin : DEFAULT_SITE,
    mode: "notify",
  });
  console.log(
    `Added ${identity.login} (${identity.id}): ${result.status}` +
      (result.isNew ? ", new user" : ", existing user") +
      (result.inboxRequested ? ", inbox issue queued" : "") +
      `${result.inbox ? `, inbox ${result.inbox}` : ""}.`,
  );
};

try {
  await main();
} finally {
  await pool?.end();
}
